```csharp
public static string[] GetFilesIncludeSubDirs(string pathToDir, params string[] extensions)
{
    List<string> result = [];

    var access = DirAccess.Open(pathToDir);
    if (access == null)
        return [];

    access.ListDirBegin();
    var name = access.GetNext();
    while (name.IsEmpty() == false)
    {
        if (access.CurrentIsDir())
        {
            result.AddRange(GetFilesIncludeSubDirs(pathToDir + "/" + name, extensions));
        }
        else
        {
            if (extensions.Length > 0)
            {
                var newName = name;

                if (OS.HasFeature("editor") == false)
                    newName = newName.TrimSuffix(".import").TrimSuffix(".remap");

                foreach (var item in extensions)
                {
                    if (newName.EndsWith(item))
                    {
                        result.Add(pathToDir + "/" + newName);
                        break;
                    }
                }
            }
            else
            {
                result.Add(pathToDir + name);
            }
        }
        name = access.GetNext();
    }
    access.ListDirEnd();

    return result.ToArray();
}
